def find_boxes(a):
 out=[]
 for r in range(18):
  for c in range(18):
   border=a[r][c]
   if border not in (2,8): continue
   for fill in set(a[r+1][c+1:c+4]):
    if fill==border:continue
    ok=all(a[rr][cc]==border for rr,cc in ([(r,c+i) for i in range(5)]+[(r+4,c+i) for i in range(5)]+[(r+i,c) for i in range(5)]+[(r+i,c+4) for i in range(5)])) and all(a[rr][cc]==fill for rr in range(r+1,r+4) for cc in range(c+1,c+4))
    if ok:out.append((r,c,border,fill))
 return sorted(set(out))
for i,u in enumerate(users):
 a=getmat(u,r'Demo pair \d+ output')
 print(i+1,find_boxes(a))

